// Finite-word magnitude plus an infinite sign extension. Printed values are
// nonnegative and fit one word; decimal update tokens need no invented bound.
struct XorInteger {
    std::vector<std::uint32_t> word;
    bool negative = false;
    void trim() { while (!word.empty() && word.back() == 0) word.pop_back(); }
    void add_small(std::uint32_t add) {
        std::uint64_t carry = add;
        for (std::size_t i = 0; carry; ++i) {
            if (i == word.size()) word.push_back(0);
            carry += word[i]; word[i] = static_cast<std::uint32_t>(carry); carry >>= 32;
        }
    }
    explicit XorInteger(const std::string& decimal = "0") {
        std::size_t start = 0;
        bool minus = false;
        if (!decimal.empty() && (decimal[0] == '-' || decimal[0] == '+')) {
            minus = decimal[0] == '-'; start = 1;
        }
        for (std::size_t i = start; i < decimal.size(); ++i) {
            std::uint64_t carry = static_cast<unsigned>(decimal[i] - '0');
            for (std::uint32_t& w : word) {
                carry += std::uint64_t(w) * 10;
                w = static_cast<std::uint32_t>(carry); carry >>= 32;
            }
            if (carry) word.push_back(static_cast<std::uint32_t>(carry));
        }
        trim();
        if (minus && !word.empty()) {
            negative = true;
            std::size_t i = 0;
            while (word[i] == 0) { word[i] = UINT32_MAX; ++i; }
            --word[i]; trim(); // -m is the complement of m-1.
        }
    }
    void combine(const XorInteger& other) {
        word.resize(std::max(word.size(), other.word.size()), 0);
        for (std::size_t i = 0; i < other.word.size(); ++i) word[i] ^= other.word[i];
        negative = negative != other.negative; trim();
    }
    std::string decimal() const {
        XorInteger magnitude = *this;
        if (negative) magnitude.add_small(1);
        if (magnitude.word.empty()) return "0";
        std::vector<std::uint32_t> digits;
        while (!magnitude.word.empty()) {
            std::uint64_t remainder = 0;
            for (std::size_t i = magnitude.word.size(); i-- > 0;) {
                const std::uint64_t current = (remainder << 32) | magnitude.word[i];
                magnitude.word[i] = static_cast<std::uint32_t>(current / 1000000000);
                remainder = current % 1000000000;
            }
            digits.push_back(static_cast<std::uint32_t>(remainder)); magnitude.trim();
        }
        std::ostringstream out;
        if (negative) out << '-';
        out << digits.back();
        for (std::size_t i = digits.size()-1; i-- > 0;) out << std::setw(9) << std::setfill('0') << digits[i];
        return out.str();
    }
};

struct XorFenwick {
    std::vector<XorInteger> bit;
    explicit XorFenwick(int n) : bit(n+2) {}
    void update(int position, const XorInteger& value) {
        for (int i = position; i < static_cast<int>(bit.size()); i += i & -i) bit[i].combine(value);
    }
    XorInteger prefix(int position) const {
        XorInteger value;
        for (int i = position; i > 0; i -= i & -i) value.combine(bit[i]);
        return value;
    }
};

int main() {
    std::freopen("cowland.in", "r", stdin);
    std::freopen("cowland.out", "w", stdout);
    std::ios::sync_with_stdio(false); std::cin.tie(nullptr);
    int n,q; if (!(std::cin >> n >> q)) return 0;
    std::vector<XorInteger> value(n), original_prefix(n);
    for (auto& v : value) { std::string token; std::cin >> token; v = XorInteger(token); }
    std::vector<std::vector<int>> edge(n);
    for (int i = 1; i < n; ++i) { int a,b; std::cin >> a >> b; --a;--b;edge[a].push_back(b);edge[b].push_back(a); }
    int levels = 1; while ((1 << levels) <= n) ++levels;
    std::vector<std::vector<int>> up(levels,std::vector<int>(n));
    std::vector<int> depth(n), enter(n), leave(n);
    struct Frame { int node,parent; bool exiting; };
    std::vector<Frame> stack{{0,0,false}};
    int clock = 0;
    while (!stack.empty()) {
        const Frame frame=stack.back();stack.pop_back();const int u=frame.node,p=frame.parent;
        if (frame.exiting) { leave[u]=clock;continue; }
        enter[u]=clock++;up[0][u]=p;
        if (u != p) depth[u]=depth[p]+1;
        original_prefix[u]=value[u];if(u!=p)original_prefix[u].combine(original_prefix[p]);
        stack.push_back({u,p,true});
        for (auto it=edge[u].rbegin();it!=edge[u].rend();++it) if(*it!=p)stack.push_back({*it,u,false});
    }
    for (int k=1;k<levels;++k) for(int u=0;u<n;++u) up[k][u]=up[k-1][up[k-1][u]];
    auto lca=[&](int a,int b) {
        if(depth[a]<depth[b])std::swap(a,b);
        const int difference=depth[a]-depth[b];
        for(int k=0;k<levels;++k)if(difference&(1<<k))a=up[k][a];
        if(a==b)return a;
        for(int k=levels-1;k>=0;--k)if(up[k][a]!=up[k][b]){a=up[k][a];b=up[k][b];}
        return up[0][a];
    };
    XorFenwick change(n);
    for(int t=0;t<q;++t) {
        int type,a;std::cin >> type >> a;--a;
        if(type==1) {
            std::string token;std::cin >> token;XorInteger updated(token),delta=value[a];delta.combine(updated);
            change.update(enter[a]+1,delta);change.update(leave[a]+1,delta);value[a]=updated;
        } else {
            int b;std::cin >> b;--b;const int common=lca(a,b);
            XorInteger answer=original_prefix[a];answer.combine(change.prefix(enter[a]+1));
            answer.combine(original_prefix[b]);answer.combine(change.prefix(enter[b]+1));answer.combine(value[common]);
            std::cout << answer.decimal() << '\n';
        }
    }
    return 0;
}
