        int x;std::cin>>x;
        if(x<last_rinsed){std::cout<<i<<'\n';return 0;}
        const auto it=std::lower_bound(bottom.begin(),bottom.end(),x);
        const int position=static_cast<int>(it-bottom.begin());
        if(position==static_cast<int>(bottom.size())){bottom.push_back(x);stack.push_back({x});}
        else {
            while(!stack[position].empty()&&stack[position].back()<x){last_rinsed=stack[position].back();stack[position].pop_back();}
            stack[position].push_back(x);
        }
    }
    std::cout<<n<<'\n';return 0;
}
